from pathlib import Path
p=Path(__file__).parent/'dist'
nav=[('/','Home'),('/diensten/','Diensten'),('/realisaties/','Realisaties'),('/over/','Over Hydrocare')]
arrow='<span aria-hidden="true">↗</span>'
def button(text,link='/contact/',cls='button'):
 return f'<a class="{cls}" href="{link}">{text} {arrow}</a>'
def photo(name,alt,cl='',eager=False):
 return f'<img class="{cl}" src="/assets/{name}.webp" srcset="/assets/{name}-800.webp 800w, /assets/{name}.webp 1800w" sizes="(max-width:700px) 100vw, 65vw" alt="{alt}" width="1800" height="1350" loading="{"eager" if eager else "lazy"}">'
def intro(kicker,title,desc):
 return f'<section class="page-intro wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{desc}</p></section>'
def cta():
 return '<section class="cta wrap"><div><p class="eyebrow">Uw project begint met een bericht</p><h2>Laat zien wat er<br>mag opfrissen.</h2><p>Een korte beschrijving en een paar foto’s zijn een goed begin.</p></div>'+button('Vraag vrijblijvend een offerte aan')+'</section>'
services='''<div class="service-grid"><article class="service"><span class="num">01 / DAK</span><h3>Dakreiniging &amp; ontmossing</h3><p>De aangeleverde dakbeelden tonen het verschil tussen een dak met mos en een gereinigd dakvlak.</p><a href="/diensten/#dak">Bekijk dit werkgebied <span aria-hidden="true">↗</span></a></article><article class="service"><span class="num">02 / DAKGOOT</span><h3>Dakgootreiniging</h3><p>Detailbeelden van werkzaamheden aan dakgoten, met de echte situatie van dichtbij in beeld.</p><a href="/diensten/#dakgoot">Bekijk dit werkgebied <span aria-hidden="true">↗</span></a></article><article class="service service-blue"><span class="num">UW PROJECT</span><h3>Wat heeft uw woning nodig?</h3><p>Beschrijf uw vraag. Daan kan aangeven of Hydrocare de juiste partij is voor uw werkzaamheden.</p><a href="/contact/">Bespreek uw project <span aria-hidden="true">↗</span></a></article></div>'''
notice='<p class="editor-note">Voorstel op basis van de projectfoto’s. De precieze diensten en werkwijze worden nog door Daan bevestigd.</p>'
comparison='<div class="compare-grid"><figure><button class="image-button" data-image="/assets/dak-voor.webp" data-caption="Dak met zichtbaar mos">'+photo('dak-voor','Grijs pannendak met zichtbaar mos')+'<span class="image-tag">Met mos</span><span class="zoom">Vergroten ↗</span></button></figure><figure><button class="image-button" data-image="/assets/dak-resultaat.webp" data-caption="Hetzelfde dak zonder het zichtbare mos">'+photo('dak-resultaat','Hetzelfde grijze pannendak zonder het zichtbare mos')+'<span class="image-tag">Gereinigd dakvlak</span><span class="zoom">Vergroten ↗</span></button></figure></div>'
steps='''<div class="steps"><article><span>01</span><h3>Vertel wat u nodig hebt.</h3><p>Geef uw gemeente door en omschrijf kort de werkzaamheden. Foto’s helpen om de situatie te bekijken.</p></article><article><span>02</span><h3>Bespreek de mogelijkheden.</h3><p>Stem met Daan af welke aanpak bij uw project past en wat nodig is voor een offerte.</p></article><article><span>03</span><h3>Maak duidelijke afspraken.</h3><p>Na akkoord spreekt u samen de werkzaamheden en de planning af.</p></article></div>'''
faq='''<div class="faq"><details><summary>In welke regio werkt Hydrocare?</summary><p>Hydrocare is actief in de provincies Antwerpen en Limburg. Vermeld uw postcode en gemeente bij uw vraag.</p></details><details><summary>Moet ik bellen voor een offerte?</summary><p>Nee. Daan geeft de voorkeur aan een bericht via e-mail, WhatsApp of Messenger. De definitieve contactkoppelingen volgen na bevestiging.</p></details><details><summary>Welke foto’s zijn handig?</summary><p>Een overzichtsfoto en een detail van de situatie helpen om uw vraag te begrijpen. Maak alleen foto’s vanaf een veilige, bereikbare plek.</p></details><details><summary>Kan ik via deze preview een aanvraag indienen?</summary><p>Dit is een websitevoorstel. Het formulier laat de aanvraagroute zien, maar verstuurt of bewaart geen aanvragen.</p></details></div>'''
home='''<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="dot"></span> Antwerpen &amp; Limburg</p><h1>Een frisse blik<br>op uw <em>dak.</em></h1><p class="lead">Bekijk reinigingswerk aan daken en dakgoten. Bespreek uw project rechtstreeks met Daan, actief in Antwerpen en Limburg.</p>'''+button('Vraag vrijblijvend een offerte aan')+button('Bekijk het werk','/realisaties/','text-link')+'''<p class="hero-foot">Persoonlijk contact. Gewoon via een bericht.</p></div><div class="hero-visual">'''+photo('dak-resultaat','Aangeleverd projectbeeld van een gereinigd pannendak',eager=True)+'''<div class="hero-label"><span>HYDROCARE / IN BEELD</span><strong>Het werk spreekt<br>voor zich.</strong><a href="/realisaties/" aria-label="Bekijk alle realisaties">↗</a></div><div class="vertical-label">ECHTE PROJECTBEELDEN</div></div></section><div class="proof-bar"><span>Rechtstreeks met Daan</span><span>Antwerpen &amp; Limburg</span><span>Foto’s van eigen werkzaamheden</span><span>Vrijblijvend uw project bespreken</span></div><section class="section wrap"><div class="section-heading"><div><p class="eyebrow">Van dichtbij bekeken</p><h2>Aandacht voor<br>wat boven u zit.</h2></div><p>Een verzorgde woning begint ook bovenaan. Bekijk het werk en bespreek wat nodig is voor uw dak of dakgoot.</p></div>'''+services+notice+'''</section><section class="section pale"><div class="wrap"><div class="section-heading"><div><p class="eyebrow">Geen stockfoto’s. Echt werk.</p><h2>Een verschil<br>dat u kunt zien.</h2></div>'''+button('Alle projectbeelden','/realisaties/','text-link')+'''</div>'''+comparison+'''<p class="caption">Hetzelfde dak, vanuit een iets andere hoek. De originele beelden zijn naast elkaar geplaatst, zonder het resultaat te retoucheren.</p></div></section><section class="section wrap"><p class="eyebrow">Van eerste bericht tot afspraak</p><h2>Zo begint het.</h2>'''+steps+'''</section><section class="region"><div class="wrap region-inner"><div><p class="eyebrow">Dicht bij huis</p><h2>Antwerpen.<br>Limburg.<br><em>Hydrocare.</em></h2></div><div><p class="lead">Een aanspreekpunt voor uw project in de regio.</p><p>Stuur uw gemeente en een korte beschrijving mee. Zo kan Daan gericht met u meekijken.</p>'''+button('Bespreek uw project')+'''</div></div></section><section class="section wrap"><div class="section-heading"><div><p class="eyebrow">Praktisch</p><h2>Goed om te weten.</h2></div><p>Snel duidelijkheid voor u de volgende stap zet.</p></div>'''+faq+'</section>'+cta()
diensten=intro('Werkzaamheden / conceptselectie','Uw dak en dakgoot.<br>Helder in beeld.','De aangeleverde werken geven de richting aan. Daan bevestigt nog welke diensten definitief aangeboden worden.')+f'<section class="wrap">{services}{notice}</section>'+'''<section class="section wrap split" id="dak"><div>'''+photo('dak-resultaat','Detail van het pannendak zonder zichtbaar mos')+'''</div><div><p class="eyebrow">01 / Dak</p><h2>Dakreiniging &amp; ontmossing</h2><p>Op de projectfoto’s is een pannendak te zien met mos, en hetzelfde dakvlak na het verwijderen van het zichtbare mos.</p><p>Wilt u weten wat mogelijk is voor uw dak? Bezorg Daan een overzichtsfoto, een korte beschrijving en uw gemeente. De geschikte aanpak wordt per situatie besproken.</p><p class="editor-note">Nog te bevestigen: aangeboden behandelingen, geschikte dakmaterialen en uitvoeringsmethode.</p>'''+button('Bespreek uw dak')+'''</div></section><section class="section pale" id="dakgoot"><div class="wrap split"><div><p class="eyebrow">02 / Dakgoot</p><h2>Aandacht voor<br>de dakgoot.</h2><p>De aangeleverde foto’s tonen werkzaamheden aan een dakgoot. Ze geven een concrete kijk op de situatie van dichtbij.</p><p>Omschrijf wat u opmerkt en voeg waar mogelijk een foto toe. Daan beoordeelt of uw vraag binnen het aanbod past.</p><p class="editor-note">Nog te bevestigen: exacte dienstverlening, bereikbaarheid en eventuele combinaties.</p>'''+button('Bespreek uw dakgoot')+'</div><div>'+photo('dakgoot-resultaat','Aangeleverd detailbeeld van een dakgoot')+'</div></div></section>'+cta()
realisaties=intro('Realisaties','Echt werk.<br><em>Zichtbaar verschil.</em>','Een blik op het werk van Hydrocare. Van het dakvlak tot de dakgoot, met details die u zelf kunt bekijken.')+'''<section class="wrap"><div class="gallery-toolbar" role="group" aria-label="Filter projectbeelden"><button class="chip active" data-filter="all" aria-pressed="true">Alle beelden <span>4</span></button><button class="chip" data-filter="dak" aria-pressed="false">Dak</button><button class="chip" data-filter="dakgoot" aria-pressed="false">Dakgoot</button></div><div data-group="dak"><div class="section-heading"><h2>Een dak, twee momenten.</h2><p>Dezelfde dakvorm en aansluitingen zijn herkenbaar op beide beelden.</p></div>'''+comparison+'''<p class="caption">De camerahoek verschilt. Daarom staan de beelden naast elkaar en gebruiken we geen overlappende schuifvergelijking.</p></div><div data-group="dakgoot" class="gallery-group"><div class="section-heading"><h2>Van dichtbij.</h2><p>Twee afzonderlijke dakgootbeelden. Niet voorgesteld als bevestigd voor-en-napaar.</p></div><div class="compare-grid">'''+''.join('<figure><button class="image-button" data-image="/assets/'+n+'.webp" data-caption="'+a+'">'+photo(n,a)+'<span class="zoom">Vergroten ↗</span></button><figcaption>'+a+'</figcaption></figure>' for n,a in [('dakgoot-detail','Dakgoot met zichtbare vervuiling'),('dakgoot-resultaat','Detail van werkzaamheden aan een dakgoot')])+'''</div></div></section>'''+cta()
over=intro('Over Hydrocare','Achter Hydrocare<br>staat <em>Daan.</em>','Een rechtstreeks aanspreekpunt voor uw vraag, in Antwerpen en Limburg.')+'''<section class="wrap split about"><div class="about-mark"><img src="/assets/logo.webp" alt="Hydrocare" width="990" height="740"><span>ANTWERPEN &amp; LIMBURG</span></div><div><p class="eyebrow">Persoonlijk contact</p><h2>Een goed begin?<br>Een duidelijk bericht.</h2><p>Daan ontvangt uw vraag bij voorkeur schriftelijk: via e-mail, WhatsApp of Facebook Messenger. Zo kunt u meteen een korte omschrijving en foto’s van de situatie meegeven.</p><p>Bekijk de aangeleverde werkzaamheden om een eerste indruk te krijgen. Bespreek daarna wat nodig is voor uw eigen project.</p>'''+button('Bespreek uw project')+'''<p class="editor-note">Voor de definitieve website: Daan kan hier zijn persoonlijke voorstelling en een portret toevoegen.</p></div></section><section class="section wrap"><p class="eyebrow">Duidelijk vanaf het begin</p><h2>Uw vraag, stap voor stap.</h2>'''+steps+'</section>'+cta()
contact=intro('Contact & offerte','Vertel eens.<br>Wat mag <em>opfrissen?</em>','Geef uw vraag door op het moment dat het u past. Een paar foto’s helpen om de situatie te begrijpen.')+'''<section class="wrap contact-layout"><div><aside class="contact-aside"><p class="eyebrow">Rechtstreeks met Daan</p><h2>Liever een bericht.</h2><p>Hydrocare is actief in Antwerpen en Limburg. Schriftelijk contact is de handigste route voor uw offerteaanvraag.</p><div class="contact-route"><strong>E-mail</strong><p>Het ontvangende adres wordt nog bevestigd.</p></div><button class="contact-route route-button" data-channel="WhatsApp"><span><strong>WhatsApp</strong><small>Foto’s en uw vraag in één bericht</small></span><span>↗</span></button><button class="contact-route route-button" data-channel="Messenger"><span><strong>Messenger</strong><small>Neem contact op via Facebook</small></span><span>↗</span></button><p class="caption">De contactknoppen tonen in deze preview een toelichting. Ze zijn nog niet gekoppeld aan een account of nummer.</p><p>Telefonisch contact is mogelijk, maar de juiste contactgegevens volgen nog.</p></aside></div><form id="quote-form"><div class="demo-note"><strong>Demonstratieformulier</strong><p>Er wordt niets verstuurd of opgeslagen. Gebruik voorbeeldgegevens om de aanvraagroute te testen.</p></div><div class="form-grid"><label>Naam <span>*</span><input name="naam" required autocomplete="name" maxlength="100" placeholder="Uw naam"></label><label>E-mailadres <span>*</span><input type="email" name="email" required autocomplete="email" maxlength="200" placeholder="naam@voorbeeld.be"></label><label>Telefoonnummer <small>optioneel</small><input type="tel" name="telefoon" autocomplete="tel" maxlength="30" placeholder="Uw telefoonnummer"></label><label>Postcode en gemeente <span>*</span><input name="gemeente" required autocomplete="address-level2" maxlength="120" placeholder="Bijv. 2400 Mol"></label></div><label>Waarover gaat uw vraag? <span>*</span><select name="dienst" required><option value="">Kies een onderwerp</option><option>Dak: mogelijkheden bespreken</option><option>Dakgoot: mogelijkheden bespreken</option><option>Andere vraag / ik weet het nog niet</option></select></label><label>Beschrijf kort de werkzaamheden <span>*</span><textarea name="beschrijving" required rows="5" maxlength="3000" placeholder="Wat wilt u laten bekijken? Wat valt u op?"></textarea></label><label class="upload">Foto’s toevoegen <small>optioneel · maximaal 5 foto’s, 10 MB per foto</small><input type="file" id="photos" name="photos" multiple accept="image/jpeg,image/png,image/webp,image/heic,image/heif"><span class="caption">De foto’s blijven op uw toestel en worden niet geüpload.</span></label><div id="file-list" class="file-list" aria-live="polite"></div><p id="file-error" class="error" role="alert"></p><p class="privacy-copy">Uw invoer blijft alleen tijdelijk in deze geopende pagina. Er is geen opslag, verzending, tracking of marketinginschrijving. Lees de <a href="/privacy/">privacytoelichting voor deze preview</a>.</p><button type="submit" class="button">Bekijk mijn demoaanvraag <span aria-hidden="true">↗</span></button><p class="caption">Dit is geen echte offerteaanvraag.</p></form></section>'''
privacy=intro('Privacy / tijdelijke preview','Uw gegevens<br>blijven bij u.','Deze toelichting geldt voor het websitevoorstel van Studio V voor Hydrocare, bijgewerkt op 29 oktober 2026.')+'''<section class="wrap prose"><h2>Een demonstratie, zonder aanvragen</h2><p>Het formulier verstuurt geen gegevens naar Hydrocare of Studio V. Ingevoerde tekst en geselecteerde foto’s worden alleen tijdelijk in uw browser verwerkt om de demonstratie te tonen. De website gebruikt hiervoor geen database, localStorage of marketingdiensten. Sluit de pagina om deze tijdelijke invoer te verwijderen.</p><h2>Foto’s en contactroutes</h2><p>Geselecteerde bestanden worden niet geüpload. De WhatsApp- en Messengerknoppen openen een toelichting en leiden nog niet naar een extern account. Deel in deze preview geen gevoelige of vertrouwelijke informatie.</p><h2>Cookies en technisch verkeer</h2><p>Er zijn geen analytics, advertentiepixels of marketingcookies toegevoegd. Bij het opvragen van de website ontvangt de hostinginfrastructuur technische verbindingsgegevens, zoals uw IP-adres. Voor deze preview zijn geen aanvullende log- of bewaartermijnen ingesteld.</p><h2>Vóór ingebruikname</h2><p>De definitieve verantwoordelijke, bedrijfsidentiteit, contactgegevens, verwerkers, bewaartermijnen en procedure voor privacyrechten moeten vóór een echte formulierkoppeling worden ingevuld en gecontroleerd. Deze previewtekst is geen definitieve privacyverklaring voor een operationele Hydrocare-website.</p>'''+button('Terug naar het formulier')+'</section>'
pages={'/':('Hydrocare · Een frisse blik op uw dak',home,'Bekijk de echte projectbeelden van Hydrocare in Antwerpen en Limburg en ontdek het websitevoorstel van Studio V.'),'/diensten/':('Werkzaamheden in beeld · Hydrocare',diensten,'Bekijk de voorgestelde dienstenstructuur op basis van de echte Hydrocare-projectbeelden.'),'/realisaties/':('Echte projectbeelden · Hydrocare',realisaties,'Originele foto’s van een pannendak en dakgoten, met vergelijking en vergrootbare galerij.'),'/over/':('Over Daan & Hydrocare',over,'Maak kennis met Hydrocare en Daan, actief in Antwerpen en Limburg.'),'/contact/':('Contact & vrijblijvende offerte · Hydrocare',contact,'Ontdek de laagdrempelige aanvraagroute voor Hydrocare. Dit formulier werkt in demonstratiemodus.'),'/privacy/':('Privacytoelichting preview · Hydrocare',privacy,'Lees hoe deze tijdelijke Hydrocare-preview omgaat met formulierinvoer en foto’s.')}
for route,(title,body,desc) in pages.items():
 path=p/route.strip('/')/'index.html';path.parent.mkdir(exist_ok=True,parents=True)
 links=''.join(f'<a href="{url}" '+('aria-current="page"' if route==url else '')+f'>{label}</a>' for url,label in nav)
 html=f'''<!doctype html><html lang="nl-BE"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow,noarchive"><title>{title}</title><meta name="description" content="{desc}"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:type" content="website"><meta property="og:locale" content="nl_BE"><meta property="og:image" content="https://hydrocare-klantenpreview-studio-v.warree111.chatgpt.site/assets/og.jpg"><meta property="og:url" content="https://hydrocare-klantenpreview-studio-v.warree111.chatgpt.site{route}"><link rel="icon" href="/assets/favicon.png"><link rel="stylesheet" href="/style.css"><script defer src="/app.js"></script></head><body><a class="skip" href="#main">Naar de inhoud</a><div class="preview-bar">Websitevoorstel voor Hydrocare <span>door Studio V · demonstratiemodus</span></div><header><div class="nav-wrap"><a class="brand" href="/" aria-label="Hydrocare home"><img src="/assets/logo.webp" alt="Hydrocare" width="990" height="740"></a><button class="menu-toggle" aria-expanded="false" aria-controls="main-nav">Menu <span>☰</span></button><nav id="main-nav" aria-label="Hoofdnavigatie">{links}{button('Offerte aanvragen')}</nav></div></header><main id="main">{body}</main><footer class="wrap"><div class="footer-top"><a href="/" class="footer-wordmark">HYDRO<span>CARE</span></a><p>Een frisse blik op uw dak.<br>Antwerpen &amp; Limburg</p><div>{links}<a href="/contact/">Contact &amp; offerte</a></div></div><div class="footer-bottom"><span>© 2026 Hydrocare · Websiteconcept</span><a href="/privacy/">Privacytoelichting</a><span>Ontwerp door <strong>Studio V</strong></span></div></footer><dialog id="viewer" aria-label="Projectbeeld of toelichting"><button class="dialog-close" aria-label="Sluiten">×</button><div id="dialog-content"></div></dialog></body></html>'''
 path.write_text(html)
(p/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
(p/'_headers').write_text('/*\n  X-Robots-Tag: noindex, nofollow, noarchive\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n  Content-Security-Policy: default-src \'self\'; img-src \'self\' blob:; style-src \'self\'; script-src \'self\'; connect-src \'none\'; form-action \'none\'; base-uri \'none\'; frame-ancestors \'none\'\n')
(p/'404.html').write_text(pages and (p/'index.html').read_text().replace(home,intro('404','Deze pagina bestaat niet.','Via de navigatie vindt u de projectbeelden, werkzaamheden en contactpagina.')+button('Terug naar home','/')))
